"""Messages captured from the cooler on 2026-09-06, as the receiver recorded them.

These are the vectors the decoder is checked against and the material the sample
chunks in ``contracts/samples`` are built from: real notification bytes, real
bodies in the clear, one of every battery state the cooler has been seen in, and
the one message it sent while the display was switched to °F.
"""

from dataclasses import dataclass

ADDRESS = "F4:9D:8A:C3:4F:84"
NAME = "SOLIX Everfrost 2 26L"
BOOT_ID = "b70259bb-dc6a-43f1-8eac-84925d851c2d"
SERIAL_NUMBER = "ANSDHW40F15400347"
BATTERY_SERIAL_NUMBER = "AZV17D20F14200480"
CHIP = "ESP32"
FIRMWARE = "0.0.0.3"
SECRET = "5bdccb1557ac395da3542dccebe02ac015aa95129109a955753f440a88916308"

#: The device-info reply of the handshake (cmd 0829), sent before the session was encrypted.
HANDSHAKE_FRAME = "ff093900030001082900a10103a2054553503332a307302e302e302e33a411414e534448573430463135343030333437a506f49d8ac34f849e"
HANDSHAKE_PLAIN = (
    "00a10103a2054553503332a307302e302e302e33a411414e534448573430463135343030333437a506f49d8ac34f84"
)


@dataclass(frozen=True)
class Message:
    """One captured message: the notifications it arrived in and its body in the clear."""

    frames: list[str]
    plain: str


IDLE = Message(
    frames=[
        ""
    ],
    plain="",
)

CHARGING = Message(
    frames=[
        ""
    ],
    plain="",
)

DISCHARGING = Message(
    frames=[
        ""
    ],
    plain="",
)

#: Charging finished: the battery is at 100 %, on external power, neither charging nor
#: discharging. The state byte is 3, which the first mapping of the message did not see.
FULL = Message(
    frames=[
        ""
    ],
    plain="",
)

#: The battery was taken out of the cooler: its serial number is all zeros.
BATTERY_ABSENT = Message(
    frames=[
        ""
    ],
    plain="",
)

#: The display was switched to °F: setpoint and interior are -4 °F, which is -20 °C.
FAHRENHEIT = Message(
    frames=[
        ""
    ],
    plain="",
)

#: A notification that stopped mid-frame; the receiver keeps the bytes and says why.
TORN_FRAME = "ff09fa0003010f4402f921d642336da598cdb1b4"

STATE_REPORTS = (DISCHARGING, IDLE, CHARGING, FULL, BATTERY_ABSENT, FAHRENHEIT)
